const ITEM_HEIGHT = 72;
const Row = memo(function Row({ item, onPress }: RowProps) {
  return <ProductCard name={item.name} onPress={() => onPress(item.id)} />;
});

export function ProductList({ products }: { products: Product[] }) {
  const onPress = useCallback((id: string) => router.push(`/product/${id}`), []);
  return (
    <FlatList
      data={products}
      keyExtractor={(item) => item.id}
      renderItem={({ item }) => <Row item={item} onPress={onPress} />}
      getItemLayout={(_, index) => ({ length: ITEM_HEIGHT, offset: ITEM_HEIGHT * index, index })}
    />
  );
}
